ds_on":["scn_docks_collapsed_deal"]},{"id":"scn_rivals_meet_ledger","title":"Old Apprentices","summary":"Kael corners Veya in a dockside tavern. Old friendship and old rivalry surface as he tries to charm her into trading her charts for access to the ledger records she needs.","location_id":"loc_mistral_docks","character_ids":["chr_veya","chr_kael"],"goal":"Kael wants Veya's charts to find the safest routes for the Cartel; Veya wants the shipping records he guards.","conflict":"Kael admires her skill yet cannot let her succeed, and Veya refuses to let him control her work.","outcome":"They part without a deal, but Kael lets slip that his ledger holds the original contract terms, and Veya resolves to get a look at it.","depends_on":["scn_veya_charts_arrive"]}]},{"id":"act_rising","title":"Threads and Tolls","purpose":"rising_action","scenes":[{"id":"scn_maris_secret_route","title":"Grain in the Dark","summary":"Veya travels to The Hollow, where Maris is smuggling grain around the Cartel levy. Maris reveals that grain shipments were among the first deals altered by the masked merchant.","location_id":"loc_the_hollow","character_ids":["chr_veya","chr_maris"],"goal":"Veya wants proof that the poisoned deals hit others, and Maris wants to keep The Hollow fed.","conflict":"Maris trusts slowly and suspects Veya is working for the Cartel; Veya's pride makes her bristle at being doubted.","outcome":"Maris agrees to trade secret service corridors for Veya's wind-current knowledge and shares an altered grain manifest bearing the masked merchant's sigil.","depends_on":["scn_rivals_meet_ledger"]},{"id":"scn_enforcers_close_in","title":"Enforcers on the Mill Road","summary":"Cartel enforcers, tracking Maris's smuggling routes, ambush Veya and Maris among the windmills. Maris leads them through unmapped service corridors while Veya reads the winds to time their escape.","location_id":"loc_the_hollow","character_ids":["chr_veya","chr_maris"],"goal":"Veya and Maris want to escape wi